import io
import json
import sys

sys.path.insert(0, "/workspace")
import service


class DiagnosticError(ValueError):
    def __getattr__(self, name):
        if name.startswith("__"):
            raise AttributeError(name)
        return "unspecified"


class Writer:
    def __init__(self, error):
        self.error = error
        self.calls = 0

    def write(self, stream):
        self.calls += 1
        raise self.error


rows = []
for error in [ValueError("ordinary failure"), DiagnosticError("ordinary failure")]:
    writer = Writer(error)
    try:
        status = service.export(writer, io.StringIO())
    except Exception as observed:
        rows.append([writer.calls, observed is error, None])
    else:
        rows.append([writer.calls, False, status])
print(json.dumps(rows))
